Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsfornecedoresWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsfornecedoresWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsfornecedoresWWGridState")) Endif
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFFORCODIGO" &TFforCodigo.FromString(&GridStateFilterValue.Value) &TFforCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFFORNOME" &TFforNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORNOME_SEL" &TFforNome_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORCONTATO" &TFforContato.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORCONTATO_SEL" &TFforContato_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORCNPJCPF" &TFforCnpjcpf.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORCNPJCPF_SEL" &TFforCnpjcpf_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORCIDADE" &TFforCidade.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORCIDADE_SEL" &TFforCidade_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORESTADO" &TFforEstado.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORESTADO_SEL" &TFforEstado_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORTELEFONE" &TFforTelefone.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORTELEFONE_SEL" &TFforTelefone_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFOREMAIL" &TFforEmail.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFOREMAIL_SEL" &TFforEmail_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORSTATUS_SEL" &TFforStatus_SelsJson = &GridStateFilterValue.Value &TFforStatus_Sels.FromJson(&TFforStatus_SelsJson) EndCase EndFor If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'FORNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &forNome1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'FORCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &forCodigo1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'FORCIDADE' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &forCidade1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'FORCNPJCPF' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &forCnpjcpf1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'FOREMAIL' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &forEmail1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'FORBAIRRO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &forBairro1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'FORTELEFONE' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &forTelefone1.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'FORNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &forNome2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'FORCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &forCodigo2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'FORCIDADE' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &forCidade2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'FORCNPJCPF' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &forCnpjcpf2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'FOREMAIL' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &forEmail2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'FORBAIRRO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &forBairro2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'FORTELEFONE' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &forTelefone2.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'FORNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &forNome3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'FORCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &forCodigo3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'FORCIDADE' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &forCidade3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'FORCNPJCPF' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &forCnpjcpf3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'FOREMAIL' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &forEmail3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'FORBAIRRO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &forBairro3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'FORTELEFONE' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &forTelefone3.FromString(&GridStateDynamicFilter.Value) EndCase EndIf EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadforNomeOptions'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&TFforNome = &SearchTxt &TFforNome_Sel.SetEmpty() For Each trnsfornecedores Order forNome using trnsfornecedoresWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &forNome1, &forCodigo1, &forCidade1, &forCnpjcpf1 , &forEmail1, &forBairro1, &forTelefone1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2 , &forNome2, &forCodigo2, &forCidade2, &forCnpjcpf2, &forEmail2, &forBairro2 , &forTelefone2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &forNome3, &forCodigo3 , &forCidade3, &forCnpjcpf3, &forEmail3, &forBairro3, &forTelefone3, &TFforCodigo , &TFforCodigo_To, &TFforNome, &TFforNome_Sel, &TFforContato, &TFforContato_Sel, &TFforCnpjcpf , &TFforCnpjcpf_Sel, &TFforCidade, &TFforCidade_Sel, &TFforEstado, &TFforEstado_Sel, &TFforTelefone , &TFforTelefone_Sel, &TFforEmail, &TFforEmail_Sel, &TFforStatus_Sels) Where prefCodigo = &prefCodigo
&count = 0 For Each trnsfornecedores Order forNome &count += 1 EndFor If not forNome.IsEmpty() &Option = forNome
&Options.Add(&Option) &OptionIndexes.Add(trim(&count.ToFormattedString())) EndIf If &Options.Count = 50 Exit EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
